#!/usr/bin/env Rscript

# Plot telomeric-repeat counts generated by telomere_analysis.sh.
# Inputs are supplied through --input-table and --output-dir; no machine-
# specific FASTA paths or sample names are hard-coded in this script.

suppressPackageStartupMessages(library(ggplot2))

parse_args <- function(args) {
  result <- list(input_table = NULL, output_dir = NULL)
  i <- 1L
  while (i <= length(args)) {
    key <- args[[i]]
    if (key %in% c("--input-table", "--output-dir")) {
      if (i == length(args)) stop("Missing value after ", key, call. = FALSE)
      value <- args[[i + 1L]]
      if (key == "--input-table") result$input_table <- value
      if (key == "--output-dir") result$output_dir <- value
      i <- i + 2L
    } else if (key %in% c("-h", "--help")) {
      cat("Usage: plot_telomeres_repetitions.R --input-table FILE --output-dir DIR\n")
      quit(status = 0)
    } else {
      stop("Unknown argument: ", key, call. = FALSE)
    }
  }
  if (is.null(result$input_table) || is.null(result$output_dir)) {
    stop("Both --input-table and --output-dir are required.", call. = FALSE)
  }
  result
}

clean_chromosome_number <- function(x) {
  # Accept the common PlasmoDB names (Pf3D7_01_v3), simple numeric names
  # (01), and names prefixed with chr (chr01). Non-chromosomal contigs are
  # excluded from this chromosome 1-14 ideogram.
  x <- sub("^Pf3D7_", "", x)
  x <- sub("^chr", "", x, ignore.case = TRUE)
  x <- sub("_v[0-9]+$", "", x)
  x <- sub("^0+", "", x)
  suppressWarnings(as.numeric(x))
}

prepare_fai <- function(file_path, sample_name) {
  if (!file.exists(file_path)) {
    stop("FASTA index not found: ", file_path,
         " (the Bash stage should create it with samtools faidx).", call. = FALSE)
  }
  df <- read.delim(file_path, header = FALSE, sep = "\t",
                   stringsAsFactors = FALSE, quote = "", comment.char = "")
  if (ncol(df) < 2L) stop("Malformed FASTA index: ", file_path, call. = FALSE)

  df <- df[, 1:2]
  names(df) <- c("Chr", "Length")
  df$Length <- suppressWarnings(as.numeric(df$Length))
  df$Chromosome <- clean_chromosome_number(df$Chr)
  df <- df[!is.na(df$Chromosome) & df$Chromosome >= 1 &
             df$Chromosome <= 14 & !is.na(df$Length), , drop = FALSE]

  if (nrow(df) == 0L) {
    warning("No chromosome names 1-14 could be parsed from ", file_path,
            "; this sample will not appear in the chromosome ideogram.")
    return(NULL)
  }

  df$Chromosome <- as.integer(df$Chromosome)
  df$Strain <- sample_name
  df$Start <- 0
  df
}

find_column <- function(headers, aliases) {
  idx <- match(tolower(aliases), tolower(headers), nomatch = 0L)
  idx <- idx[idx > 0L]
  if (length(idx)) idx[[1L]] else NA_integer_
}

process_tidk_repeats <- function(tsv_file, sample_name, window_size = 10000) {
  if (!file.exists(tsv_file)) {
    stop("TIDK output not found: ", tsv_file, call. = FALSE)
  }

  df <- read.delim(tsv_file, header = TRUE, stringsAsFactors = FALSE,
                   check.names = FALSE, quote = "", comment.char = "")
  if (nrow(df) == 0L) return(NULL)

  # TIDK search TSVs use id/start/forward/reverse (plus a repeat column).
  # Aliases allow the script to read outputs whose headers differ slightly.
  chr_idx <- find_column(names(df), c("id", "chr", "chromosome", "contig", "seqid"))
  start_idx <- find_column(names(df), c("start", "window_start", "position"))
  fwd_idx <- find_column(names(df), c("forward", "fwd", "forward_count", "forward_repeats"))
  rev_idx <- find_column(names(df), c("reverse", "rev", "reverse_count", "reverse_repeats"))

  # Backward-compatible positional fallback for TIDK TSVs with the standard
  # five-column layout but non-standard column labels.
  if (anyNA(c(chr_idx, start_idx, fwd_idx, rev_idx))) {
    if (ncol(df) < 4L) {
      stop("Unexpected TIDK TSV layout in ", tsv_file,
           ". Expected id, start, forward and reverse columns.", call. = FALSE)
    }
    chr_idx <- 1L
    start_idx <- 2L
    fwd_idx <- 3L
    rev_idx <- 4L
  }

  out <- data.frame(
    Chr = as.character(df[[chr_idx]]),
    Real_Start = suppressWarnings(as.numeric(df[[start_idx]])),
    Fwd = suppressWarnings(as.numeric(df[[fwd_idx]])),
    Rev = suppressWarnings(as.numeric(df[[rev_idx]])),
    stringsAsFactors = FALSE
  )
  out <- out[complete.cases(out), , drop = FALSE]
  if (nrow(out) == 0L) return(NULL)

  out$Total_Repeats <- out$Fwd + out$Rev
  out <- out[out$Total_Repeats > 10, , drop = FALSE]
  if (nrow(out) == 0L) return(NULL)

  out$Chromosome <- clean_chromosome_number(out$Chr)
  out <- out[!is.na(out$Chromosome) & out$Chromosome >= 1 &
               out$Chromosome <= 14, , drop = FALSE]
  if (nrow(out) == 0L) return(NULL)

  out$Chromosome <- as.integer(out$Chromosome)
  out$Start <- out$Real_Start
  out$End <- out$Real_Start + window_size
  out$Category <- ifelse(out$Total_Repeats >= 100, ">100 repeats",
                         ifelse(out$Total_Repeats >= 30,
                                "30-100 repeats", "10-30 repeats"))
  out$Strain <- sample_name
  out[, c("Strain", "Chromosome", "Start", "End", "Category",
          "Total_Repeats", "Fwd", "Rev")]
}

args <- parse_args(commandArgs(trailingOnly = TRUE))
if (!file.exists(args$input_table)) {
  stop("Input table not found: ", args$input_table, call. = FALSE)
}

inputs <- read.delim(args$input_table, header = TRUE, sep = "\t",
                     stringsAsFactors = FALSE, check.names = FALSE,
                     quote = "", comment.char = "")
required_columns <- c("Sample", "Fasta", "TidkTSV")
missing_columns <- setdiff(required_columns, names(inputs))
if (length(missing_columns)) {
  stop("Input table is missing column(s): ",
       paste(missing_columns, collapse = ", "), call. = FALSE)
}
if (nrow(inputs) == 0L) stop("Input table contains no samples.", call. = FALSE)

background_list <- lapply(seq_len(nrow(inputs)), function(i) {
  prepare_fai(paste0(inputs$Fasta[[i]], ".fai"), inputs$Sample[[i]])
})
background_list <- Filter(Negate(is.null), background_list)
if (length(background_list) == 0L) {
  stop("No chromosome 1-14 backgrounds could be constructed from the FAI files.",
       call. = FALSE)
}
chromosome_backgrounds <- do.call(rbind, background_list)
chromosome_backgrounds$Chromosome <- factor(
  chromosome_backgrounds$Chromosome, levels = 14:1
)

repeat_list <- lapply(seq_len(nrow(inputs)), function(i) {
  process_tidk_repeats(inputs$TidkTSV[[i]], inputs$Sample[[i]], 10000)
})
repeat_list <- Filter(Negate(is.null), repeat_list)
if (length(repeat_list)) {
  telomere_data <- do.call(rbind, repeat_list)
  telomere_data$Chromosome <- factor(telomere_data$Chromosome, levels = 14:1)
  telomere_data$Category <- factor(
    telomere_data$Category,
    levels = c(">100 repeats", "30-100 repeats", "10-30 repeats")
  )
  telomere_data <- telomere_data[order(telomere_data$Category, decreasing = TRUE), ]
} else {
  telomere_data <- data.frame(
    Strain = character(), Chromosome = factor(character(), levels = 14:1),
    Start = numeric(), End = numeric(), Category = factor(),
    Total_Repeats = numeric(), Fwd = numeric(), Rev = numeric()
  )
  warning("No telomeric windows passed the >10 repeat filter; plotting chromosome backgrounds only.")
}

# Keep the original chromosome-ideogram style while allowing any number of
# samples supplied by telomere_analysis.sh.
telo_colors <- c(">100 repeats" = "#2ECC71",
                 "30-100 repeats" = "#FFC101",
                 "10-30 repeats" = "#F57C00")

ideogram_plot <- ggplot() +
  geom_segment(
    data = chromosome_backgrounds,
    aes(x = Start, xend = Length, y = Chromosome, yend = Chromosome),
    color = "grey95", linewidth = 4, lineend = "round"
  ) +
  geom_segment(
    data = telomere_data,
    aes(x = Start, xend = End, y = Chromosome, yend = Chromosome,
        color = Category),
    linewidth = 3, lineend = "round"
  ) +
  facet_wrap(~Strain, ncol = 2, scales = "free_x") +
  scale_color_manual(values = telo_colors,
                     name = "Telomeric repeat\nsequence region", drop = FALSE) +
  scale_x_continuous(labels = function(x) paste0(x / 1000000, "Mbp")) +
  scale_y_discrete(labels = function(x) sprintf("chr%02d", as.numeric(as.character(x)))) +
  labs(x = "Length (Mbp)", y = "") +
  theme_minimal() +
  theme(
    panel.grid.major.y = element_blank(),
    panel.grid.minor = element_blank(),
    axis.text.y = element_text(face = "bold", size = 9, color = "black"),
    strip.text = element_text(face = "bold", size = 13)
  )

if (!dir.exists(args$output_dir)) {
  dir.create(args$output_dir, recursive = TRUE, showWarnings = FALSE)
}

pdf_file <- file.path(args$output_dir, "telomeric_repeats.pdf")
png_file <- file.path(args$output_dir, "telomeric_repeats.png")
ggsave(filename = pdf_file, plot = ideogram_plot, width = 10, height = 10)
ggsave(filename = png_file, plot = ideogram_plot, width = 12, height = 10, dpi = 300)

message("Telomere figures written to: ", normalizePath(args$output_dir))
